blocks.text:
וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם; וְאֵרַשְׂתִּיךְ לִי בְּצֶדֶק וּבְמִשְׁפָּט וּבְחֶסֶד וּבְרַחֲמִים; וְאֵרַשְׂתִּיךְ לִי בֶּאֱמוּנָה, וְיָדַעְתְּ אֶת י~הוה;

וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; קַדֶּשׁ לִי כָל בְּכוֹר פֶּטֶר כָּל רֶחֶם בִּבְנֵי יִשְׂרָאֵל בָּאָדָם וּבַבְּהֵמָה, לִי הוּא; וַיֹּאמֶר מֹשֶׁה אֶל הָעָם זָכוֹר אֶת הַיּוֹם הַזֶּה אֲשֶׁר יְצָאתֶם מִמִּצְרַיִם מִבֵּית עֲבָדִים, כִּי בְּחֹזֶק יָד הוֹצִיא י~הוה אֶתְכֶם מִזֶּה, וְלֹא יֵאָכֵל חָמֵץ; הַיּוֹם אַתֶּם יֹצְאִים, בְּחֹדֶשׁ הָאָבִיב; וְהָיָה כִי יְבִיאֲךָ י~הוה אֶל אֶרֶץ הַכְּנַעֲנִי וְהַחִתִּי וְהָאֱמֹרִי וְהַחִוִּי וְהַיְבוּסִי אֲשֶׁר נִשְׁבַּע לַאֲבֹתֶיךָ לָתֶת לָךְ, אֶרֶץ זָבַת חָלָב וּדְבָשׁ, וְעָבַדְתָּ אֶת הָעֲבֹדָה הַזֹּאת בַּחֹדֶשׁ הַזֶּה; שִׁבְעַת יָמִים תֹּאכַל מַצֹּת וּבַיּוֹם הַשְּׁבִיעִי חַג לַי~הוה; מַצּוֹת יֵאָכֵל אֵת שִׁבְעַת הַיָּמִים, וְלֹא יֵרָאֶה לְךָ חָמֵץ וְלֹא יֵרָאֶה לְךָ שְׂאֹר בְּכָל גְּבֻלֶךָ; וְהִגַּדְתָּ לְבִנְךָ בַּיּוֹם הַהוּא לֵאמֹר, בַּעֲבוּר זֶה עָשָׂה י~הוה לִי בְּצֵאתִי מִמִּצְרָיִם; וְהָיָה לְךָ לְאוֹת עַל יָדְךָ וּלְזִכָּרוֹן בֵּין עֵינֶיךָ, לְמַעַן תִּהְיֶה תּוֹרַת י~הוה בְּפִיךָ, כִּי בְּיָד חֲזָקָה הוֹצִאֲךָ י~הוה מִמִּצְרָיִם; וְשָׁמַרְתָּ אֶת הַחֻקָּה הַזֹּאת לְמוֹעֲדָהּ, מִיָּמִים יָמִימָה;

וְהָיָה כִּי יְבִאֲךָ י~הוה אֶל אֶרֶץ הַכְּנַעֲנִי כַּאֲשֶׁר נִשְׁבַּע לְךָ וְלַאֲבֹתֶיךָ, וּנְתָנָהּ לָךְ; וְהַעֲבַרְתָּ כָל פֶּטֶר רֶחֶם לַי~הוה, וְכָל פֶּטֶר שֶׁגֶר בְּהֵמָה אֲשֶׁר יִהְיֶה לְךָ הַזְּכָרִים לַי~הוה; וְכָל פֶּטֶר חֲמֹר תִּפְדֶּה בְשֶׂה, וְאִם לֹא תִפְדֶּה וַעֲרַפְתּוֹ, וְכֹל בְּכוֹר אָדָם בְּבָנֶיךָ תִּפְדֶּה; וְהָיָה כִּי יִשְׁאָלְךָ בִנְךָ מָחָר לֵּאמֹר מַה זֹּאת, וְאָמַרְתָּ אֵלָיו, בְּחֹזֶק יָד הוֹצִיאָנוּ י~הוה מִמִּצְרַיִם מִבֵּית עֲבָדִים; וַיְהִי כִּי הִקְשָׁה פַרְעֹה לְשַׁלְּחֵנוּ, וַיַּהֲרֹג י~הוה כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם, מִבְּכֹר אָדָם וְעַד בְּכוֹר בְּהֵמָה, עַל כֵּן אֲנִי זֹבֵחַ לַי~הוה כָּל פֶּטֶר רֶחֶם הַזְּכָרִים וְכָל בְּכוֹר בָּנַי אֶפְדֶּה; וְהָיָה לְאוֹת עַל יָדְכָה וּלְטוֹטָפֹת בֵּין עֵינֶיךָ, כִּי בְּחֹזֶק יָד הוֹצִיאָנוּ י~הוה מִמִּצְרָיִם;

לְעוֹלָם יְהֵא אָדָם יְרֵא שָׁמַיִם בְּסֵתֶר וּבַגָּלוּי, וּמוֹדֶה עַל הָאֱמֶת, וְדוֹבֵר אֱמֶת בִּלְבָבוֹ, וְיַשְׁכֵּם וְיֹאמַר:

רִבּוֹן כָּל הָעוֹלָמִים, וַאֲדוֹנֵי הָאֲדוֹנִים . לֹא עַל צִדְקוֹתֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵינוּ לְפָנֶיךָ, כִּי עַל רַחֲמֶיךָ הָרַבִּים. מָה אֲנַחְנוּ, מֶה חַיֵּינוּ, מֶה חַסְדֵּנוּ, מַה צִדְקוֹתֵינוּ, מַה יְּשׁוּעָתֵנוּ, מַה כֹּחֵנוּ, מַה גְּבוּרָתֵנוּ. מַה נֹּאמַר לְפָנֶיךָ י~הוה אֱ~לֹהֵינוּ וֵא~לֹהֵי אֲבוֹתֵינוּ, הֲלֹא כָּל הַגִּבּוֹרִים כְּאַיִן לְפָנֶיךָ, וְאַנְשֵׁי הַשֵּׁם כְּלֹא הָיוּ, וַחֲכָמִים כִּבְלִי מַדָּע, וּנְבוֹנִים כִּבְלִי הַשְׂכֵּל, כִּי רוֹב מַעֲשֵׂיהֶם תֹּהוּ, וִימֵי חַיֵּיהֶם הֶבֶל לְפָנֶיךָ, וּמוֹתַר הָאָדָם מִן הַבְּהֵמָה אָיִן, כִּי הַכֹּל הָבֶל; 

אֲבָל אֲנַחְנוּ עַמְּךָ בְּנֵי בְרִיתֶךָ, בְּנֵי אַבְרָהָם אֹהַבְךָ שֶׁנִּשְׁבַּעְתָּ לּוֹ בְּהַר הַמּוֹרִיָּה, זֶרַע יִצְחָק יְחִידוֹ שֶׁנֶּעֱקַד עַל גַּבֵּי הַמִּזְבֵּחַ, עֲדַת יַעֲקֹב בִּנְךָ בְּכוֹרֶךָ, שֶׁמֵּאַהֲבָתְךָ שֶׁאָהַבְתָּ אוֹתוֹ וּמִשִּׂמְחָתְךָ שֶׁשָּׂמַחְתָּ בּוֹ קָרָאתָ אֶת שְׁמוֹ יִשְׂרָאֵל וִישֻׁרוּן.

לְפִיכָךְ אֲנַחְנוּ חַיָּבִים לְהוֹדוֹת לְךָ, וּלְשַׁבֵּחֲךָ וּלְפָאֶרְךָ וּלְבָרֵךְ וּלְקַדֵּשׁ וְלָתֵת שֶׁבַח וְהוֹדָיָה לִשְׁמֶךָ. אַשְׁרֵינוּ, מַה טּוֹב חֶלְקֵנוּ, וּמַה נָּעִים גּוֹרָלֵנוּ, וּמַה יָּפָה יְרֻשָּׁתֵנוּ, אַשְׁרֵינוּ, כְּשֶׁאֲנַחְנוּ מַשְׁכִּימִים וּמַעֲרִיבִים בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת, וּמְיַחֲדִים שִׁמְךָ בְּכָל יוֹם תָּמִיד וְאוֹמְרִים פַּעֲמַיִם בְּאַהֲבָה:

שְׁמַע יִשְׂרָאֵל, י~הוה אֱ~לֹהֵינוּ, י~הוה אֶחָד;

בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.

וְאָהַבְתָּ אֵת י~הוה אֱ~לֹהֶיךָ, בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ; וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם, עַל לְבָבֶךָ; וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם, בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ; וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ, וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ; וּכְתַבְתָּם עַל מְזוּזֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ;

אַתָּה הוּא עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, אַתָּה הוּא מִשֶּׁנִּבְרָא הָעוֹלָם, אַתָּה הוּא בָּעוֹלָם הַזֶּה, וְאַתָּה הוּא לָעוֹלָם הַבָּא. קַדֵּשׁ אֶת שִׁמְךָ עַל מַקְדִּישֵׁי שְׁמֶךָ, וְקַדֵּשׁ אֶת שִׁמְךָ בְּעוֹלָמֶךָ, וּבִישׁוּעָתְךָ מַלְכֵּנוּ תָּרוּם וְתַגְבִּיהַּ קַרְנֵנוּ לְמַעְלָה לְמַעְלָה, וְהוֹשִׁיעֵנוּ בְּקָרוֹב לְמַעַן שְׁמֶךָ. בָּרוּךְ הַמְקַדֵּשׁ שְׁמוֹ הַגָדוֹל בָּרַבִּים.

אַתָּה הוּא י~הוה אֱ~לֹהֵינוּ בַּשָּׁמַיִם וּבָאָרֶץ וּבִשְׁמֵי הַשָּׁמַיִם הָעֶלְיוֹנִים. אַתָּה הוּא וּשְׁנוֹתֶיךָ לא יִתָּמּוּ. אֱמֶת, אַתָּה הוּא רִאשׁוֹן וְאַתָּה הוּא אַחֲרוֹן וּמִבַּלְעָדֶיךָ אֵין אֱ~לֹהִים. קַבֵּץ נְפוּצוֹת קֹוֶיךָ מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ. יַכִּירוּ וְיֵדְעוּ כָּל בָּאֵי עוֹלָם, כִּי אַתָּה הוּא הָאֱ~לֹהִים לְבַדְּךָ עליון לְכֹל מַמְלְכוֹת הָאָרֶץ. אַתָּה עָשִׂיתָ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם, וּמִי בְּכָל מַעֲשֵׂי יָדֶיךָ בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים שֶׁיֹּאמַר לְךָ מַה תַּעֲשֶׂה וּמַה תִּפְעָל. אָבִינוּ שֶׁבַּשָּׁמַיִם חַי וְקַיָּם, עֲשֵׂה עִמָּנוּ צְדָקָה וָחֶסֶד בַּעֲבוּר שִׁמְךָ הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא שֶׁנִּקְרָא עָלֵינוּ, וְקַיֶּם לָנוּ י~הוה אֱ~לֹהֵינוּ אֶת הַדָּבָר שֶׁהִבְטַחְתָּנוּ עַל יְדֵי צְפַנְיָה חוֹזָךְ, כָּאָמוּר: בָּעֵת הַהִיא אָבִיא אֶתְכֶם, וּבָעֵת קַבְּצִי אֶתְכֶם, כִּי אֶתֵּן אֶתְכֶם לְשֵׁם וְלִתְהִלָּה בְּכֹל עַמֵּי הָאָרֶץ, בְּשׁוּבִי אֶת שְׁבוּתֵיכֶם לְעֵינֵיכֶם, אָמַר י~הוה;

יְהִי רָצוֹן מִלְּפָנֶיךָ י~הוה אֱ~לֹהֵינוּ וֵא~לֹהֵי אֲבוֹתֵינוּ, שֶׁתְּרַחֵם עָלֵינוּ 
וּתְכַפֶּר לָנוּ עַל כָּל חַטֹּאתֵינוּ וְתִסְלַח לָנוּ עַל כָּל עֲוׂנוֹתֵינוּ וְתִמְחֹל לָנוּ עַל כָּל פְּשָׁעֵינוּ, 
וְשֶׁיִבָּנֶה בֵּית הַמִּקְדָּשׁ בִּּמְהֵרָה בְיָמֵינוּ, וְנַקְרִיב לְפָנֶיךָ קָרְבַּן הַתָּמִיד שֶׁיְּכַפֵּר בַּעֲדֵנוּ, כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ עַל יְדֵי מֹשֶׁה עַבְדֶּךָ מִפִּי כְבוֹדֶךָ, כָּאָמוּר:

וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; צַו אֶת בְּנֵי יִשרָאֵל וְאָמַרְתָּ אֲלֵהֶם, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, רֵיחַ נִיחֹחִי, תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ; וְאָמַרְתָּ לָהֶם, זֶה הָאִשֶּׁה אֲשֶׁר תַּקְרִיבוּ לַי~הוה, כְּבָשִׂים בְּנֵי שָׁנָה תְמִימִים, שְׁנַיִם לַיּוֹם עֹלָה תָמִיד; אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַבֹּקֶר, וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם; וַעֲשִׂירִית הָאֵיפָה סֹלֶת לְמִנְחָה, בְּלוּלָה בְּשֶׁמֶן כָּתִית רְבִיעִת הַהִין; עֹלַת תָּמִיד, הָעֲשֻׂיָה בְּהַר סִינַי, לְרֵיחַ נִיחֹחַ אִשֶּׁה לַי~הוה; וְנִסְכּוֹ רְבִיעִת הַהִין לַכֶּבֶשׂ הָאֶחָד, בַּקֹּדֶשׁ הַסֵּךְ נֶסֶךְ שֵׁכָר לַי~הוה; וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם, כְּמִנְחַת הַבֹּקֶר וּכְנִסְכּוֹ תַּעֲשֶׂה, אִשֵּׁה רֵיחַ נִיחֹחַ לַי~הוה;

וְשָׁחַט אֹתוֹ עַל יֶרֶךְ הַמִּזְבֵּחַ צָפֹנָה לִפְנֵי י~הוה, וְזָרְקוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֶת דָּמוֹ עַל הַמִּזְבֵּחַ סָבִיב;

אַתָּה הוּא י~הוה אֱ~לֹהֵינוּ שֶׁהִקְטִירוּ אֲבוֹתֵינוּ לְפָנֶיךָ אֶת קְטֹרֶת הַסַּמִּים בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ הָיָה קַיָּם, כַּאֲשֶׁר צִוִּיתָ אוֹתָם עַל יַד מֹשֶׁה נְבִיאֶךָ, כַּכָּתוּב בְּתוֹרָתֶךָ:
וַיֹּאמֶר י~הוה אֶל מֹשֶׁה, קַח לְךָ סַמִּים נָטָף וּשְׁחֵלֶת וְחֶלְבְּנָה סַמִּים וּלְבֹנָה זַכָּה בַּד בְּבַד יִהְיֶה; וְעָשִׂיתָ אֹתָהּ קְטֹרֶת, רֹקַח מַעֲשֶׂה רוֹקֵחַ, מְמֻלָּח טָהוֹר קֹדֶשׁ; וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק, וְנָתַתָּה מִמֶּנָּה לִפְנֵי הָעֵדֻת בְּאֹהֶל מוֹעֵד אֲשֶׁר אִוָּעֵד לְךָ שָׁמָּה, קֹדֶשׁ קָדָשִׁים תִּהְיֶה לָכֶם; וְנֶאֱמַר: וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים, בַּבֹּקֶר בַּבֹּקֶר בְּהֵיטִיבוֹ אֶת הַנֵּרוֹת יַקְטִירֶנָּה; וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה, קְטֹרֶת תָּמִיד לִפְנֵי י~הוה לְדֹרֹתֵיכֶם;

תָּנוּ רַבָּנָן: פִּטּוּם הַקְּטֹרֶת כֵּיצַד? שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וּשְׁמוֹנָה מָנִים הָיוּ בָהּ. שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה כְּמִנְיַן יְמוֹת הַחַמָּה, מָנֶה לְכָל יוֹם, פְּרַס בְּשַׁחֲרִית וּפְרַס בֵּין הָעַרְבָּיִם. וּשְׁלֹשָׁה מָנִים יְתֵרִים שֶׁמֵּהֶם מַכְנִיס כֹּהֵן גָּדוֹל מְלֹא חָפְנָיו בְּיוֹם הַכִּפּוּרִים, וּמַחֲזִירָן לְמַכְתֶּשֶׁת בְּעֶרֶב יום הַכִּפּוּרִים, וְשׁוֹחֲקָן יָפֶה יָפֶה כְּדֵי לְקַיֵּם מִצְוַת דַקָּה מִן הַדַּקָּה.

וְאַחַד עָשר סַמְמָנִים הָיוּ בָהּ, וְאֵלּוּ הֵן: (א) הַצֳּרִי (ב) וְהַצִּפֹּרֶן, (ג) וְהַחֶלְבְּנָה (ד) וְהַלְּבוֹנָה מִשְׁקַל שִׁבְעִים שִׁבְעִים מָנֶה, (ה) מֹר (ו) וּקְצִיעָה, (ז) שִׁבֹּלֶת נֵרְדְּ (ח) וְכַרְכֹּם מִשְׁקַל שִׁשָּׁה עָשָׂר שִׁשָּׁה עָשָׂר מָנֶה, (ט) הַקֹּסְטְ שְׁנֵים עָשָׂר, (י) וְקִלּוּפָה שְׁלֹשָׁה, (יא) וְקִנָּמון תִּשְׁעָה, בֹּרִית כַּרְשִׁינָה תִּשְׁעָה קַבִּין, יֵין קַפְרִיסִין סְאִין תְּלָתָא וְקַבִּין תְּלָתָא, וְאִם אֵין לוׂ יֵין קַפְרִיסִין מֵבִיא חֲמַר חִוַּרְיָן עַתִּיק. מֶלַח סְדוֹמִית רֹבַע מַעֲלֶה עָשָׁן כָּל שֶׁהוּא. רַבִּי נָתָן הַבַּבְלִי אוֹמֵר: אַף כִּפַּת הַיַּרְדֵּן כָּל שֶׁהוּא. וְאִם נָתַן בָּהּ דְּבַשׁ פְּסָלָהּ, וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב.

רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר: הַצֳּרִי אֵינוֹ אֶלָּא שְׂרָף הַנּוֹטֵף מֵעֲצֵי הַקְּטָף. בֹּרִית כַּרְשִׁינָה לָמָה הִיא בָאָה כְדֵי לְיַפוֹת בָּה אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא נָאֶה. יֵין קַפְרִיסִין שֶׁשׁוֹרִין בּוֹ אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא עַזָּה. וַהֲלֹא מֵי רַגְלַיִם יָפִין לָהּ, אֶלָּא שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם בַּעֲזָרָה מִפְּנֵי הַכָּבוֹד.

תַּנְיָא: רַבִּי נָתָן אוֹמֵר: כְּשֶׁהוּא שׁוֹחֵק אוֹמֵר: הָדֵק הֵיטֵב, הֵיטֵב הָדֵק, מִפְּנֵי שֶׁהַקּוֹל יָפֶה לַבְּשָׂמִים. פִּטְּמָהּ לַחֲצָאִין כְּשֵׁרָה. לִשְׁלִישׁ וְלִרְבִיעַ לֹא שָׁמַעְנוּ. אָמַר רַבִּי יְהוּדָה: זֶה הַכְּלָל: אִם כְּמִדָּתָהּ כְּשֵׁרָה לַחֲצָאִין, וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב .

תַּנְיָא: בַּר קַפָּרָא אוֹמֵר: אַחַת לְשִׁשִּׁים אוֹ לְשִׁבְעִים שָׁנָה הָיְתָה בָאָה שֶׁל שִׁירַיִם לַחֲצָאִין. וְעוֹד תָּנֵי בַּר קַפָּרָא: אִלּוּ הָיָה נוֹתֵן בָּהּ קוֹרְטוֹב שֶׁל דְּבַשׁ אֵין אָדָם יָכוֹל לַעֲמֹד מִפְּנֵי רֵיחָהּ, וְלָמָּה אֵין מְעָרְבִין בָּהּ דְּבַשׁ? מִפְּנֵי שֶׁהַתּוֹרָה אָמְרָה כִּי כָל שְׂאֹר וְכָל דְּבַשׁ לֹא תַקְטִירוּ מִמֶּנּוּ אִשֶּׁה לַי~הוה;

י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;

י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;
י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;
י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;

י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;
י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;
י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;

אַתָּה סֵתֶר לִי מִצַּר תִּצְּרֵנִי רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה; 
וְעָרְבָה לַי~הוה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיּות;

הוֹדוּ לַי~הוה קִרְאוֹ בִשְׁמוֹ, הוֹדִיעוּ בָעַמִּים עֲלִילוֹתָיו; שִׁירוּ לוֹ זַמְּרוּ לוֹ, שִׂיחוּ בְּכָל נִפְלְאוֹתָיו; הִתְהַלְלוּ בְּשֵׁם קָדְשׁוֹ, יִשְׂמַח לֵב מְבַקְשֵׁי י~הוה; דִּרְשׁוּ י~הוה וְעֻזּוֹ, בַּקְּשׁוּ פָנָיו תָּמִיד; זִכְרוּ נִפְלְאוֹתָיו אֲשֶׁר עָשָׂה, מֹפְתָיו וּמִשְׁפְּטֵי פִיהוּ; זֶרַע יִשְׂרָאֵל עַבְדּוֹ, בְּנֵי יַעֲקֹב בְּחִירָיו; הוּא י~הוה אֱ~לֹהֵינוּ בְּכָל הָאָרֶץ מִשְׁפָּטָיו; זִכְרוּ לְעוֹלָם בְּרִיתוֹ, דָּבָר צִוָּה לְאֶלֶף דּוֹר; אֲשֶׁר כָּרַת אֶת אַבְרָהָם, וּשְׁבוּעָתוֹ לְיִצְחָק; וַיַּעֲמִידֶהָ לְיַעֲקֹב לְחֹק, לְיִשְׂרָאֵל בְּרִית עוֹלָם; לֵאמֹר, לְךָ אֶתֵּן אֶרֶץ כְּנָעַן, חֶבֶל נַחֲלַתְכֶם; בִּהְיוֹתְכֶם מְתֵי מִסְפָּר, כִּמְעַט וְגָרִים בָּהּ; וַיִּתְהַלְּכוּ מִגּוֹי אֶל גּוֹי וּמִמַּמְלָכָה אֶל עַם אַחֵר; לֹא הִנִּיחַ לְאִישׁ לְעָשְׁקָם, וַיּוֹכַח עֲלֵיהֶם מְלָכִים; אַל תִּגְּעוּ בִּמְשִׁיחָי, וּבִנְבִיאַי אַל תָּרֵעוּ; שִׁירוּ לַי~הוה כָּל הָאָרֶץ, בַּשְּׂרוּ מִיּוֹם אֶל יוֹם יְשׁוּעָתוֹ; סַפְּרוּ בַגּוֹיִם אֶת כְּבוֹדוֹ, בְּכָל הָעַמִּים נִפְלְאֹתָיו; כִּי גָדוֹל י~הוה וּמְהֻלָּל מְאֹד, וְנוֹרָא הוּא עַל כָּל אֱלֹהִים; כִּי כָּל אֱלֹהֵי הָעַמִּים אֱלִילִים,(כאן צריך להפסיק) וַי~הוה שָׁמַיִם עָשָׂה; הוֹד וְהָדָר לְפָנָיו, עֹז וְחֶדְוָה בִּמְקֹמוֹ; הָבוּ לַי~הוה מִשְׁפְּחוֹת עַמִּים, הָבוּ לַי~הוה כָּבוֹד וָעֹז; הָבוּ לַי~הוה כְּבוֹד שְׁמוֹ, שְׂאוּ מִנְחָה וּבֹאוּ לְפָנָיו, הִשְׁתַּחֲווּ לַי~הוה בְּהַדְרַת קֹדֶשׁ; חִילוּ מִלְּפָנָיו כָּל הָאָרֶץ, אַף תִּכּוֹן תֵּבֵל בַּל תִּמּוֹט; יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ, וְיֹאמְרוּ בַגּוֹיִם י~הוה מָלָךְ; יִרְעַם הַיָּם וּמְלוֹאוֹ, יַעֲלֹץ הַשָּׂדֶה וְכָל אֲשֶׁר בּוֹ; אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי י~הוה, כִּי בָא לִשְׁפּוֹט אֶת הָאָרֶץ; הוֹדוּ לַי~הוה כִּי טוֹב, כִּי לְעוֹלָם חַסְדּוֹ; וְאִמְרוּ, הוֹשִׁיעֵנוּ אֱ~לֹהֵי יִשְׁעֵנוּ וְקַבְּצֵנוּ וְהַצִּילֵנוּ מִן הַגּוֹיִם, לְהֹדוֹת לְשֵׁם קָדְשֶׁךָ, לְהִשְׁתַּבֵּחַ בִּתְהִלָּתֶךָ; בָּרוּךְ י~הוה אֱ~לֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעֹלָם, וַיֹּאמְרוּ כָל הָעָם אָמֵן וְהַלֵּל לַי~הוה; רוֹמְמוּ י~הוה אֱ~לֹהֵינוּ וְהִשְׁתַּחֲווּ לַהֲדֹם רַגְלָיו, קָדוֹשׁ הוּא; רוֹמְמוּ י~הוה אֱ~לֹהֵינוּ וְהִשְׁתַּחֲווּ לְהַר קָדְשׁוֹ, כִּי קָדוֹשׁ י~הוה אֱ~לֹהֵינוּ; 
וְהוּא רַחוּם יְכַפֵּר עָוׂן וְלֹא יַשְׁחִית, וְהִרְבָּה לְהָשִׁיב אַפּוֹ וְלֹא יָעִיר כָּל חֲמָתוֹ; 
אַתָּה י~הוה לֹא תִכְלָא רַחֲמֶיךָ מִמֶּנִּי, חַסְדְּךָ וַאֲמִתְּךָ תָּמִיד יִצְּרוּנִי; זְכֹר רַחֲמֶיךָ י~הוה, וַחֲסָדֶיךָ, כִּי מֵעוֹלָם הֵמָּה; תְּנוּ עֹז לֵא~לֹהִים, עַל יִשְׂרָאֵל גַּאֲוָתוֹ וְעֻזּוֹ בַּשְּׁחָקִים; נוֹרָא אֱ~לֹהִים מִמִּקְדָּשֶׁיךָ אֵ~ל יִשְׂרָאֵל, הוּא נֹתֵן עֹז וְתַעֲצֻמוֹת לָעָם, בָּרוּךְ אֱ~לֹהִים; אֵ~ל נְקָמוֹת י~הוה, אֵ~ל נְקָמוֹת הוֹפִיעַ; הִנָּשֵׂא שֹׁפֵט הָאָרֶץ, הָשֵׁב גְּמוּל עַל גֵּאִים; לַי~הוה הַיְשׁוּעָה עַל עַמְּךָ בִרְכָתֶךָ, סֶּלָה; י~הוה צְ~בָאוֹת עִמָּנוּ מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב, סֶלָה; י~הוה צְ~בָאוֹת אַשְׁרֵי אָדָם בֹּטֵחַ בָּךְ; י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ; הוֹשִׁיעָה אֶת עַמֶּךָ וּבָרֵךְ אֶת נַחֲלָתֶךָ, וּרְעֵם וְנַשְּׂאֵם עַד הָעוֹלָם; נַפְשֵׁנוּ חִכְּתָה לַי~הוה, עֶזְרֵנוּ וּמָגִנֵּנוּ הוּא; כִּי בוֹ יִשְׂמַח לִבֵּנוּ כִּי בְשֵׁם קָדְשׁוֹ בָטָחְנוּ; יְהִי חַסְדְּךָ י~הוה עָלֵינוּ כַּאֲשֶׁר יִחַלְנוּ לָךְ; הַרְאֵנוּ י~הוה חַסְדֶּךָ, וְיֶשְׁעֲךָ תִּתֶּן לָנוּ; קוּמָה עֶזְרָתָה לָּנוּ וּפְדֵנוּ לְמַעַן חַסְדֶּךָ; אָנֹכִי י~הוה אֱ~לֹהֶיךָ הַמַּעַלְךָ מֵאֶרֶץ מִצְרָיִם, הַרְחֶב פִּיךָ וַאֲמַלְאֵהוּ; אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ, אַשְׁרֵי הָעָם שֶׁי~הוה אֱ~לֹהָיו; וַאֲנִי בְּחַסְדְּךָ בָטַחְתִּי, יָגֵל לִבִּי בִּישׁוּעָתֶךָ, אָשִׁירָה לַי~הוה כִּי גָמַל עָלָי;

מִזְמוֹר שִׁיר חֲנֻכַּת הַבַּיִת לְדָוִד; אֲרוֹמִמְךָ י~הוה כִּי דִלִּיתָנִי, וְלֹא שִׂמַּחְתָּ אֹיְבַי לִי; י~הוה אֱ~לֹהָי שִׁוַּעְתִּי אֵלֶיךָ וַתִּרְפָּאֵנִי; י~הוה, הֶעֱלִיתָ מִן שְׁאוֹל נַפְשִׁי, חִיִּיתַנִי מִיָּרְדִי בוֹר; זַמְּרוּ לַי~הוה חֲסִידָיו וְהוֹדוּ לְזֵכֶר קָדְשׁוֹ; כִּי רֶגַע בְּאַפּוֹ חַיִּים בִּרְצוֹנוֹ, בָּעֶרֶב יָלִין בֶּכִי וְלַבֹּקֶר רִנָּה; וַאֲנִי אָמַרְתִּי בְשַׁלְוִי בַּל אֶמּוֹט לְעוֹלָם; י~הוה בִּרְצוֹנְךָ הֶעֱמַדְתָּה לְהַרְרִי עֹז, הִסְתַּרְתָּ פָנֶיךָ הָיִיתִי נִבְהָל; אֵלֶיךָ י~הוה אֶקְרָא וְאֶל אֲ~דֹנָי אֶתְחַנָּן; מַה בֶּצַע בְּדָמִי בְּרִדְתִּי אֶל שָׁחַת, הֲיוֹדְךָ עָפָר הֲיַגִּיד אֲמִתֶּךָ; שְׁמַע י~הוה וְחָנֵּנִי, י~הוה הֱיֵה עֹזֵר לִי; הָפַכְתָּ מִסְפְּדִי לְמָחוֹל לִי, פִּתַּחְתָּ שַׂקִּי וַתְּאַזְּרֵנִי שִׂמְחָה; לְמַעַן יְזַמֶּרְךָ כָבוֹד וְלֹא יִדֹּם, י~הוה אֱ~לֹהַי לְעוֹלָם אוֹדֶךָּ;

י~הוה מֶלֶךְ, י~הוה מָלָךְ, י~הוה יִמְלֹך לְעֹלָם וָעֵד.
י~הוה מֶלֶךְ, י~הוה מָלָךְ, י~הוה יִמְלֹך לְעֹלָם וָעֵד.
וְהָיָה י~הוה לְמֶלֶךְ עַל כָּל הָאָרֶץ, בַּיּוֹם הַהוּא יִהְיֶה י~הוה אֶחָד וּשְׁמוֹ אֶחָד;

הוֹשִׁיעֵנוּ י~הוה אֱ~לֹהֵינוּ וְקַבְּצֵנוּ מִן הַגּוֹיִם, לְהוֹדוֹת לְשֵׁם קָדְשֶׁךָ לְהִשְׁתַּבֵּחַ בִּתְהִלָּתֶךָ; בָּרוּךְ י~הוה אֱ~לֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם, וְאָמַר כָּל הָעָם אָמֵן, הַלְלוּיָ~הּ; כֹּל הַנְּשָׁמָה תְּהַלֵּל יָ~הּ, הַלְלוּיָ~הּ;

הֲרֵינִי מְזַמֵּן אֶת פִּי לְהוֹדוֹת וּלְהַלֵּל וּלְשַׁבֵּחַ אֶת בּוֹרְאִי לְשֵׁם יִחוּד קֻדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ עַל יְדֵי הַהוּא טָמִיר וְנֶעְלָם בְּשֵׁם כָּל יִשְׂרָאֵל. וִיהִי נֹעַם אֲ~דֹנָי אֱ~לֹהֵינוּ עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ;

בָּרוּךְ שֶׁאָמַר וְהָיָה הָעוֹלָם, בָּרוּךְ הוּא, בָּרוּךְ אוֹמֵר וְעוֹשֶׂה, בָּרוּךְ גּוֹזֵר וּמְקַיֵּם, בָּרוּךְ עוֹשֶׂה בְּרֵאשִׁית, בָּרוּךְ מְרַחֵם עַל הָאָרֶץ, בָּרוּךְ מְרַחֵם עַל הַבְּרִיּוֹת, בָּרוּךְ מְשַׁלֵּם שָׂכָר טוֹב לִירֵאָיו, בָּרוּךְ חַי לָעַד וְקַיָּם לָנֶצַח, בָּרוּךְ פּוֹדֶה וּמַצִּיל, בָּרוּךְ שְׁמוֹ. בָּרוּךְ אַתָּה י~הוה, אֱ~לֹהֵינוּ מֶלֶךְ הָעוֹלָם, הָאֵ~ל אָב הָרַחֲמָן הַמְהֻלָּל בְּפֶה עַמּוֹ, מְשֻׁבָּח וּמְפֹאָר בִּלְשׁוֹן חֲסִידָיו וַעֲבָדָיו, וּבְשִׁירֵי דָּוִד עַבְדֶּךָ נְהַלֶלְךָ י~הוה אֱ~לֹהֵינוּ בִּשְׁבָחוֹת וּבִזְמִירוֹת, וּנְגַדֶּלְךָ וּנְשַׁבֶּחֲךָ וּנְפָאֶרְךָ וְנַמְלִיכְךָ וְנַזְכִּיר שִׁמְךָ מַלְכֵּנוּ אֱ~לֹהֵינוּ, יָחִיד חֵי הָעוֹלָמִים, מֶלֶךְ מְשֻׁבָּח וּמְפֹאָר עֲדֵי עַד שְׁמוֹ הַגָּדוֹל. בָּרוּךְ אַתָּה י~הוה, מֶלֶךְ מְהֻלָּל בַּתִּשְׁבָּחוֹת.


יְהִי כְבוֹד י~הוה לְעוֹלָם, יִשְׂמַח י~הוה בְּמַעֲשָׂיו; יְהִי שֵׁם י~הוה מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם; מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ מְהֻלָּל שֵׁם י~הוה; רָם עַל כָּל גּוֹיִם י~הוה, עַל הַשָּׁמַיִם כְּבוֹדוֹ; י~הוה שִׁמְךָ לְעוֹלָם, י~הוה זִכְרְךָ לְדֹר וָדֹר; י~הוה בַּשָּׁמַיִם הֵכִין כִּסְאוֹ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה; יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ, וְיֹאמְרוּ בַגּוֹיִם י~הוה מָלָךְ; י~הוה מֶלֶךְ, י~הוה מָלָךְ, י~הוה יִמְלֹךְ לְעוֹלָם וָעֶד. י~הוה מֶלֶךְ עוֹלָם וָעֶד, אָבְדוּ גוֹיִם מֵאַרְצוֹ; י~הוה הֵפִיר עֲצַת גּוֹיִם, הֵנִיא מַחְשְׁבוֹת עַמִּים; רַבּוֹת מַחֲשָׁבוֹת בְּלֶב אִישׁ, וַעֲצַת י~הוה הִיא תָקוּם; עֲצַת י~הוה לְעוֹלָם תַּעֲמֹד, מַחְשְׁבוֹת לִבּוֹ לְדֹר וָדֹר; כִּי הוּא אָמַר וַיֶּהִי, הוּא צִוָּה וַיַּעֲמֹד; כִּי בָחַר י~הוה בְּצִיּוֹן, אִוָּהּ לְמוֹשָׁב לוֹ; כִּי יַעֲקֹב בָּחַר לוֹ יָ~הּ, יִשְׂרָאֵל לִסְגֻלָּתוֹ; כִּי לֹא יִטֹּשׁ י~הוה עַמּוֹ וְנַחֲלָתוֹ לֹא יַעֲזֹב;
וְהוּא רַחוּם יְכַפֵּר עָוׂן וְלֹא יַשְׁחִית, וְהִרְבָּה לְהָשִׁיב אַפּוֹ וְלֹא יָעִיר כָּל חֲמָתוֹ; 
י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;

אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ עוֹד יְהַלְלוּךָ סֶּלָה;
אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁי~הוה אֱ~לֹהָיו;
תְּהִלָּה לְדָוִד, אֲרוֹמִמְךָ אֱ~לוֹהַי הַמֶּלֶךְ וַאֲבָרְכָה שִׁמְךָ לְעוֹלָם וָעֶד;
בְּכָל יוֹם אֲבָרְכֶךָּ וַאֲהַלְלָה שִׁמְךָ לְעוֹלָם וָעֶד;
גָּדוֹל י~הוה וּמְהֻלָּל מְאֹד וְלִגְדֻלָּתוֹ אֵין חֵקֶר;
דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךָ וּגְבוּרֹתֶיךָ יַגִּידוּ;
הֲדַר כְּבוֹד הוֹדֶךָ וְדִבְרֵי נִפְלְאוֹתֶיךָ אָשִׂיחָה;
וֶעֱזוּז נוֹרְאֹתֶיךָ יֹאמֵרוּ וּגְדוּלָּתְךָ אֲסַפְּרֶנָּה;
זֵכֶר רַב טוּבְךָ יַבִּיעוּ וְצִדְקָתְךָ יְרַנֵּנוּ;
חַנּוּן וְרַחוּם י~הוה אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד;
טוֹב י~הוה לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו;
יוֹדוּךָ י~הוה כָּל מַעֲשֶׂיךָ וַחֲסִידֶיךָ יְבָרְכוּכָה;
כְּבוֹד מַלְכוּתְךָ יֹאמֵרוּ וּגְבוּרָתְךָ יְדַבֵּרוּ;
לְהוֹדִיעַ לִבְנֵי הָאָדָם גְּבוּרֹתָיו וּכְבוֹד הֲדַר מַלְכוּתוֹ;
מַלְכוּתְךָ מַלְכוּת כָּל עֹלָמִים וּמֶמְשֶׁלְתְּךָ בְּכָל דּוֹר וָדוֹר;
סוֹמֵךְ י~הוה לְכָל הַנֹּפְלִים וְזוֹקֵף לְכָל הַכְּפוּפִים;
עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ;
פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן;
צַדִּיק י~הוה בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו;
קָרוֹב י~הוה לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת;
רְצוֹן יְרֵאָיו יַעֲשֶׂה וְאֶת שַׁוְעָתָם יִשְׁמַע וְיוֹשִׁיעֵם;
שׁוֹמֵר י~הוה אֶת כָּל אֹהֲבָיו וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד;
תְּהִלַּת י~הוה יְדַבֶּר פִּי וִיבָרֵךְ כָּל בָּשָׂר שֵׁם קָדְשׁוֹ לְעוֹלָם וָעֶד;
וַאֲנַחְנוּ נְבָרֵךְ יָ~הּ מֵעַתָּה וְעַד עוֹלָם הַלְלוּיָ~הּ; הַלְלוּיָ~הּ.

הַלְלִי נַפְשִׁי אֶת י~הוה; אֲהַלְלָה י~הוה בְּחַיָּי, אֲזַמְּרָה לֵא~לֹהַי בְּעוֹדִי; אַל תִּבְטְחוּ בִנְדִיבִים, בְּבֶן אָדָם שֶׁאֵין לוֹ תְשׁוּעָה; תֵּצֵא רוּחוֹ, יָשֻׁב לְאַדְמָתוֹ, בַּיּוֹם הַהוּא אָבְדוּ עֶשְׁתֹּנֹתָיו; אַשְׁרֵי שֶׁאֵ~ל יַעֲקֹב בְּעֶזְרוֹ, שִׂבְרוֹ עַל י~הוה אֱ~לֹהָיו; עֹשֶׂה שָׁמַיִם וָאָרֶץ, אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם, הַשֹּׁמֵר אֱמֶת לְעוֹלָם; עֹשֶׂה מִשְׁפָּט לָעֲשׁוּקִים, נֹתֵן לֶחֶם לָרְעֵבִים, י~הוה מַתִּיר אֲסוּרִים; י~הוה פֹּקֵחַ עִוְרִים, י~הוה זֹקֵף כְּפוּפִים, י~הוה אֹהֵב צַדִּיקִים; י~הוה שֹׁמֵר אֶת גֵּרִים, יָתוֹם וְאַלְמָנָה יְעוֹדֵד וְדֶרֶךְ רְשָׁעִים יְעַוֵּת; יִמְלֹךְ י~הוה לְעוֹלָם, אֱ~לֹהַיִךְ צִיּוֹן לְדֹר וָדֹר, הַלְלוּיָ~הּ; הַלְלוּיָ~הּ. 

כִּי טוֹב זַמְּרָה אֱ~לֹהֵינוּ, כִּי נָעִים נָאוָה תְהִלָּה; בּוֹנֵה יְרוּשָׁלַיִם י~הוה, נִדְחֵי יִשְׂרָאֵל יְכַנֵּס; הָרֹפֵא לִשְׁבוּרֵי לֵב וּמְחַבֵּשׁ לְעַצְּבוֹתָם; מוֹנֶה מִסְפָּר לַכּוֹכָבִים, לְכֻלָּם שֵׁמוֹת יִקְרָא; גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ, לִתְבוּנָתוֹ אֵין מִסְפָּר; מְעוֹדֵד עֲנָוִים י~הוה, מַשְׁפִּיל רְשָׁעִים עֲדֵי אָרֶץ; עֱנוּ לַי~הוה בְּתוֹדָה, זַמְּרוּ לֵא~לֹהֵינוּ בְכִנּוֹר; הַמְכַסֶּה שָׁמַיִם בְּעָבִים, הַמֵּכִין לָאָרֶץ מָטָר, הַמַּצְמִיחַ הָרִים חָצִיר; נוֹתֵן לִבְהֵמָה לַחְמָהּ, לִבְנֵי עֹרֵב אֲשֶׁר יִקְרָאוּ; לֹא בִגְבוּרַת הַסּוּס יֶחְפָּץ, לֹא בְשׁוֹקֵי הָאִישׁ יִרְצֶה; רוֹצֶה י~הוה אֶת יְרֵאָיו, אֶת הַמְיַחֲלִים לְחַסְדּוֹ; שַׁבְּחִי יְרוּשָׁלַיִם אֶת י~הוה, הַלְלִי אֱ~לֹהַיִךְ צִיּוֹן; כִּי חִזַּק בְּרִיחֵי שְׁעָרָיִךְ, בֵּרַךְ בָּנַיִךְ בְּקִרְבֵּךְ; הַשָּׂם גְּבוּלֵךְ שָׁלוֹם, חֵלֶב חִטִּים יַשְׂבִּיעֵךְ; הַשֹּׁלֵחַ אִמְרָתוֹ אָרֶץ, עַד מְהֵרָה יָרוּץ דְּבָרוֹ; הַנֹּתֵן שֶׁלֶג כַּצָּמֶר, כְּפוֹר כָּאֵפֶר יְפַזֵּר; מַשְׁלִיךְ קַרְחוֹ כְפִתִּים, לִפְנֵי קָרָתוֹ מִי יַעֲמֹד; יִשְׁלַח דְּבָרוֹ וְיַמְסֵם, יַשֵּׁב רוּחוֹ יִזְּלוּ מָיִם; מַגִּיד דְּבָרָיו לְיַעֲקֹב, חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל; לֹא עָשָׂה כֵן לְכָל גּוֹי, וּמִשְׁפָּטִים בַּל יְדָעוּם, הַלְלוּיָ~הּ; הַלְלוּיָ~הּ. 

הַלְלוּ אֶת י~הוה מִן הַשָּׁמַיִם, הַלְלוּהוּ בַּמְּרוֹמִים; הַלְלוּהוּ כָל מַלְאָכָיו, הַלְלוּהוּ כָּל צְבָאָיו; הַלְלוּהוּ שֶׁמֶשׁ וְיָרֵחַ, הַלְלוּהוּ כָּל כּוֹכְבֵי אוֹר; הַלְלוּהוּ שְׁמֵי הַשָּׁמָיִם וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם; יְהַלְלוּ אֶת שֵׁם י~הוה, כִּי הוּא צִוָּה וְנִבְרָאוּ; וַיַּעֲמִידֵם לָעַד לְעוֹלָם, חָק נָתַן וְלֹא יַעֲבוֹר; הַלְלוּ אֶת י~הוה מִן הָאָרֶץ, תַּנִּינִים וְכָל תְּהֹמוֹת; אֵשׁ וּבָרָד, שֶׁלֶג וְקִיטוֹר, רוּחַ סְעָרָה עֹשָׂה דְבָרוֹ; הֶהָרִים וְכָל גְּבָעוֹת, עֵץ פְּרִי וְכָל אֲרָזִים; הַחַיָּה וְכָל בְּהֵמָה, רֶמֶשׂ וְצִפּוֹר כָּנָף; מַלְכֵי אֶרֶץ וְכָל לְאֻמִּים, שָׂרִים וְכָל שֹׁפְטֵי אָרֶץ; בַּחוּרִים וְגַם בְּתוּלוֹת, זְקֵנִים עִם נְעָרִים; יְהַלְלוּ אֶת שֵׁם י~הוה כִּי נִשְׂגָּב שְׁמוֹ לְבַדּוֹ, הוֹדוֹ עַל אֶרֶץ וְשָׁמָיִם; וַיָּרֶם קֶרֶן לְעַמּוֹ, תְּהִלָּה לְכָל חֲסִידָיו, לִבְנֵי יִשְׂרָאֵל עַם קְרֹבוֹ, הַלְלוּיָ~הּ; הַלְלוּיָ~הּ. 

שִׁירוּ לַי~הוה שִׁיר חָדָשׁ, תְּהִלָּתוֹ בִּקְהַל חֲסִידִים; יִשְׂמַח יִשְׂרָאֵל בְּעֹשָׂיו, בְּנֵי צִיּוֹן יָגִילוּ בְמַלְכָּם; יְהַלְלוּ שְׁמוֹ בְמָחוֹל, בְּתֹף וְכִנּוֹר יְזַמְּרוּ לוֹ; כִּי רוֹצֶה י~הוה בְּעַמּוֹ, יְפָאֵר עֲנָוִים בִּישׁוּעָה; יַעְלְזוּ חֲסִידִים בְּכָבוֹד, יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם; רוֹמְמוֹת אֵ~ל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם; לַעֲשׂוֹת נְקָמָה בַּגּוֹיִם, תּוֹכֵחֹת בַּלְאֻמִּים; לֶאְסֹר מַלְכֵיהֶם בְּזִקִּים וְנִכְבְּדֵיהֶם בְּכַבְלֵי בַרְזֶל; לַעֲשׂוֹת בָּהֶם מִשְׁפָּט כָּתוּב, הָדָר הוּא לְכָל חֲסִידָיו, הַלְלוּיָ~הּ; הַלְלוּיָ~הּ. 

הַלְלוּ אֵ~ל בְּקָדְשׁוֹ, הַלְלוּהוּ בִּרְקִיעַ עֻזּוֹ; הַלְלוּהוּ בִגְבוּרֹתָיו, הַלְלוּהוּ כְּרֹב גֻּדְלוֹ; הַלְלוּהוּ בְּתֵקַע שׁוֹפָר, הַלְלוּהוּ בְּנֵבֶל וְכִנּוֹר; הַלְלוּהוּ בְתֹף וּמָחוֹל, הַלְלוּהוּ בְּמִנִּים וְעוּגָב; הַלְלוּהוּ בְצִלְצְלֵי שָׁמַע, הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה; כֹּל הַנְּשָׁמָה תְּהַלֵּל יָ~הּ, הַלְלוּיָ~הּ; כֹּל הַנְּשָׁמָה תְּהַלֵּל יָ~הּ, הַלְלוּיָ~הּ;

בָּרוּךְ י~הוה לְעוֹלָם, אָמֵן וְאָמֵן; בָּרוּך י~הוה מִצִּיּוֹן, שֹׁכֵן יְרוּשָלַיִם, הַלְלוּיָ~הּ; בָּרוּךְ י~הוה אֱ~לֹהִים אֱ~לֹהֵי יִשְׂרָאֵל, עֹשֶׂה נִפְלָאוֹת לְבַדּוֹ; וּבָרוּךְ שֵׁם כְּבוֹדוֹ לְעוֹלָם, וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָרֶץ, אָמֵן וְאָמֵן;

וַיְבָרֶךְ דָּוִד אֶת י~הוה לְעֵינֵי כָּל הַקָּהָל, וַיֹּאמֶר דָּוִד: בָּרוּךְ אַתָּה י~הוה אֱ~לֹהֵי יִשְׂרָאֵל אָבִינוּ, מֵעוֹלָם וְעַד עוֹלָם; לְךָ י~הוה הַגְּדֻלָּה, וְהַגְּבוּרָה, וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד, כִּי כָל בַּשָּׁמַיִם וּבָאָרֶץ, לְךָ י~הוה הַמַּמְלָכָה וְהַמִּתְנַשֵּׂא לְכָל לְרֹאשׁ; וְהָעֹשֶׁר וְהַכָּבוֹד מִלְּפָנֶיךָ, וְאַתָּה מוֹשֵׁל בַּכֹּל, וּבְיָדְךָ כֹּחַ וּגְבוּרָה וּבְיָדְךָ לְגַדֵּל וּלְחַזֵּק לַכֹּל; וְעַתָּה אֱ~לֹהֵינוּ מוֹדִים אֲנַחְנוּ לָךְ, וּמְהַלְלִים לְשֵׁם תִפְאַרְתֶּךְ; וִיבָרְכוּ שֵׁם כְּבֹדֶָךָ, וּמֱרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה; אַתָּה הוּא י~הוה לְבַדֶּךָ, אַתָּה עָשִׂיתָ אֶת הַשָּׁמַיִם, שְׁמֵי הַשָּׁמַיִם וְכָל צְבָאָם, הָאָרֶץ וְכָל אֲשֶׁר עָלֶיהָ, הַיַּמִּים וְכָל אֲשֶׁר בָּהֶם, וְאַתָּה מְחַיֶּה אֶת כֻּלָּם, וּצְבָא הַשָּׁמַיִם לְךָ מִשְׁתַּחֲוִים; אַתָּה הוּא י~הוה הָאֱ~לֹהִים אֲשֶׁר בָּחַרְתָּ בְּאַבְרָם וְהוֹצֵאתוֹ מֵאוּר כַּשְׂדִּים, וְשַׂמְתָּ שְׁמוֹ אַבְרָהָם; וּמָצָאתָ אֶת לְבָבוֹ נֶאֱמָן לְפָנֶיךָ.

וְכָרוֹת עִמּוֹ הַבְּרִית לָתֵת אֶת אֶרֶץ הַכְּנַעֲנִי, הַחִתִּי, הָאֱמֹרִי וְהַפְּרִזִּי וְהַיְבוּסִי וְהַגִּרְגָּשִׁי לָתֵת לְזַרְעוֹ, וַתָּקֶם אֶת דְּבָרֶיךָ כִּי צַדִּיק אָתָּה; וַתֵּרֶא אֶת עֳנִי אֲבֹתֵינוּ בְּמִצְרָיִם, וְאֶת זַעֲקָתָם שָׁמַעְתָּ עַל יַם סוּף; וַתִּתֵּן אֹתֹת וּמֹפְתִים בְּפַרְעֹה וּבְכָל עֲבָדָיו וּבְכָל עַם אַרְצוֹ, כִּי יָדַעְתָּ כִּי הֵזִידוּ עֲלֵיהֶם, וַתַּעַשׂ לְךָ שֵׁם כְּהַיּוֹם הַזֶּה; וְהַיָּם בָּקַעְתָּ לִפְנֵיהֶם, וַיַּעַבְרוּ בְתוֹךְ הַיָּם בַּיַּבָּשָׁה, וְאֶת רֹדְפֵיהֶם הִשְׁלַכְתָּ בִמְצוֹלֹת כְּמוֹ אֶבֶן, בְּמַיִם עַזִּים;

וַיּוֹשַׁע י~הוה בַּיּוֹם הַהוּא אֶת יִשְׂרָאֵל מִיַּד מִצְרָיִם, וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, עַל שְׂפַת הַיָּם; וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדֹלָה אֲשֶׁר עָשָׂה י~הוה בְּמִצְרַיִם, וַיִּירְאוּ הָעָם אֶת י~הוה, וַיַּאֲמִינוּ בַּי~הוה וּבְמֹשֶׁה עַבְדּוֹ;

בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.

וְאָהַבְתָּ אֵת י~הוה אֱ~לֹהֶיךָ, בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ; וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם, עַל לְבָבֶךָ; וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם, בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ; וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ, וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ; וּכְתַבְתָּם עַל מְזוּזֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ;

וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ אֶל מִצְוׂתַי, אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם הַיּוֹם, לְאַהֲבָה אֶת י~הוה אֱ~לֹהֵיכֶם וּלְעָבְדוֹ, בְּכָל לְבַבְכֶם וּבְכָל נַפְשְׁכֶם; וְנָתַתִּי מְטַר אַרְצְכֶם בְּעִתּוֹ, יוֹרֶה וּמַלְקוֹשׁ, וְאָסַפְתָּ דְגָנֶךָ וְתִירֹשְׁךָ וְיִצְהָרֶךָ; וְנָתַתִּי עֵשֶׂב בְּשָׂדְךָ לִבְהֶמְתֶּךָ, וְאָכַלְתָּ וְשָׂבָעְתָּ; הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם, וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם; וְחָרָה אַף י~הוה בָּכֶם, וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר, וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ, וַאֲבַדְתֶּם מְהֵרָה מֵעַל הָאָרֶץ הַטֹּבָה אֲשֶׁר י~הוה נֹתֵן לָכֶם; וְשַׂמְתֶּם אֶת דְּבָרַי אֵלֶּה עַל לְבַבְכֶם וְעַל נַפְשְׁכֶם, וּקְשַׁרְתֶּם אֹתָם לְאוֹת עַל יֶדְכֶם וְהָיוּ לְטוֹטָפֹת בֵּין עֵינֵיכֶם; וְלִמַּדְתֶּם אֹתָם אֶת בְּנֵיכֶם לְדַבֵּר בָּם, בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ; וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ; לְמַעַן יִרְבּוּ יְמֵיכֶם וִימֵי בְנֵיכֶם עַל הָאֲדָמָה אֲשֶׁר נִשְׁבַּע י~הוה לַאֲבֹתֵיכֶם לָתֵת לָהֶם, כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ;

וַיֹּאמֶר י~הוה אֶל מֹשֶׁה לֵּאמֹר; דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם, וְעָשׂוּ לָהֶם צִיצִת עַל כַּנְפֵי בִגְדֵיהֶם לְדֹרֹתָם, וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת; וְהָיָה לָכֶם לְצִיצִת, וּרְאִיתֶם אֹתוֹ, וּזְכַרְתֶּם אֶת כָּל מִצְוׂת י~הוה וַעֲשִׂיתֶם אֹתָם, וְלֹא תָתֻרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זֹנִים אַחֲרֵיהֶם; לְמַעַן תִּזְכְּרוּ וַעֲשִׂיתֶם אֶת כָּל מִצְוׂתָי, וִהְיִיתֶם קְדֹשִׁים לֵא~לֹהֵיכֶם; אֲנִי י~הוה אֱ~לֹהֵיכֶם אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם, לִהְיוֹת לָכֶם לֵא~לֹהִים, אֲנִי י~הוה אֱ~לֹהֵיכֶם;
אֱמֶת

יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ, י~הוה צוּרִי וְגוֹאֲלִי;

עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל, וְאִמְרוּ אָמֵן.

יְהִי רָצוֹן מִלְּפָנֶיךָ י~הוה אֱ~לֹהֵינוּ וֵא~לֹהֵי אֲבוֹתֵינוּ, שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְּיָמֵינוּ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיּוֹת. וְעָרְבָה לַי~הוה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמֹנִיּוֹת;

אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ עוֹד יְהַלְלוּךָ סֶּלָה;
אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁי~הוה אֱ~לֹהָיו;
תְּהִלָּה לְדָוִד, אֲרוֹמִמְךָ אֱ~לוֹהַי הַמֶּלֶךְ וַאֲבָרְכָה שִׁמְךָ לְעוֹלָם וָעֶד;
בְּכָל יוֹם אֲבָרְכֶךָּ וַאֲהַלְלָה שִׁמְךָ לְעוֹלָם וָעֶד;
גָּדוֹל י~הוה וּמְהֻלָּל מְאֹד וְלִגְדֻלָּתוֹ אֵין חֵקֶר;
דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךָ וּגְבוּרֹתֶיךָ יַגִּידוּ;
הֲדַר כְּבוֹד הוֹדֶךָ וְדִבְרֵי נִפְלְאוֹתֶיךָ אָשִׂיחָה;
וֶעֱזוּז נוֹרְאֹתֶיךָ יֹאמֵרוּ וּגְדוּלָּתְךָ אֲסַפְּרֶנָּה;
זֵכֶר רַב טוּבְךָ יַבִּיעוּ וְצִדְקָתְךָ יְרַנֵּנוּ;
חַנּוּן וְרַחוּם י~הוה אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד;
טוֹב י~הוה לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו;
יוֹדוּךָ י~הוה כָּל מַעֲשֶׂיךָ וַחֲסִידֶיךָ יְבָרְכוּכָה;
כְּבוֹד מַלְכוּתְךָ יֹאמֵרוּ וּגְבוּרָתְךָ יְדַבֵּרוּ;
לְהוֹדִיעַ לִבְנֵי הָאָדָם גְּבוּרֹתָיו וּכְבוֹד הֲדַר מַלְכוּתוֹ;
מַלְכוּתְךָ מַלְכוּת כָּל עֹלָמִים וּמֶמְשֶׁלְתְּךָ בְּכָל דּוֹר וָדוֹר;
סוֹמֵךְ י~הוה לְכָל הַנֹּפְלִים וְזוֹקֵף לְכָל הַכְּפוּפִים;
עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ;
פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן;
צַדִּיק י~הוה בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו;
קָרוֹב י~הוה לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת;
רְצוֹן יְרֵאָיו יַעֲשֶׂה וְאֶת שַׁוְעָתָם יִשְׁמַע וְיוֹשִׁיעֵם;
שׁוֹמֵר י~הוה אֶת כָּל אֹהֲבָיו וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד;
תְּהִלַּת י~הוה יְדַבֶּר פִּי וִיבָרֵךְ כָּל בָּשָׂר שֵׁם קָדְשׁוֹ לְעוֹלָם וָעֶד;
וַאֲנַחְנוּ נְבָרֵךְ יָ~הּ מֵעַתָּה וְעַד עוֹלָם הַלְלוּיָ~הּ;


וּבָא לְצִיּוֹן גּוֹאֵל, וּלְשָׁבֵי פֶשַׁע בְּיַעֲקֹב, נְאֻם י~הוה;
וַאֲנִי זֹאת בְּרִיתִי אוֹתָם, אָמַר י~הוה, רוּחִי אֲשֶׁר עָלֶיךָ וּדְבָרַי אֲשֶׁר שַׂמְתִּי בְּפִיךָ, לֹא יָמוּשׁוּ מִפִּיךָ וּמִפִּי זַרְעֲךָ וּמִפִּי זֶרַע זַרְעֲךָ, אָמַר י~הוה, מֵעַתָּה וְעַד עוֹלָם;

