יִתְגַּדֵּל וְיִתְקַדֵּשׁ שְׁמֵהּ רַבָּא.
בְּעָלְמָא דִּי בְּרָא כִּרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ וְיַצְמַח פֻּרְקָנֵהּ וִיקַרֵב מְשִׁיחֵהּ.
בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל, בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן.
יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאֵר וְיִתְרוֹמֵם וְיִתְנַשֵּׂא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא בְּרִיךְ הוּא.
לְעֵלָּא מִן כָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחֱמָתָא, דַּאֲמִירָן בְּעָלְמָא, וְאִמְרוּ אָמֵן.
תִּתְקַבֵּל צְלוֹתְהוֹן וּבָעוּתְהוֹן דְּכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא וְאַרְעָא, וְאִמְרוּ אָמֵן.
יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים טוֹבִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן.
עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל, וְאִמְרוּ אָמֵן.






קַוֵּה אֶל ה'. חֲזַק וְיַאֲמֵץ לִבֶּךָ. וְקַוֵּה אֶל ה': 
אֵין קָדושׁ כַּיהוָה. כִּי אֵין בִּלְתֶּךָ. וְאֵין צוּר כֵּאלהֵינוּ: 
כִּי מִי אֱלוהַּ מִבַּלְעֲדֵי ה'. וּמִי צוּר זוּלָתִי אֱלהֵינוּ: 

אֵין כֵּאלהֵינוּ. אֵין כַּאדוֹנֵינוּ. אֵין כְּמַלְכֵּנוּ. אֵין כְּמושִׁיעֵנוּ: 
מִי כֵאלהֵינוּ. מִי כַאדוֹנֵינוּ. מִי כְמַלְכֵּנוּ. מִי כְמושִׁיעֵנוּ: 
נודֶה לֵאלהֵינוּ. נודֶה לַאדוֹנֵינוּ. נודֶה לְמַלְכֵּנוּ. נודֶה לְמושִׁיעֵנוּ: 
בָּרוּךְ אֱלהֵינוּ. בָּרוּךְ אֲדוֹנֵינוּ. בָּרוּךְ מַלְכֵּנוּ. בָּרוּךְ מושִׁיעֵנוּ: 
אַתָּה הוּא אֱלהֵינוּ. אַתָּה הוּא אֲדוֹנֵינוּ. אַתָּה הוּא מַלְכֵּנוּ. אַתָּה הוּא מושִׁיעֵנוּ. אַתָּה תושִׁיעֵנוּ: 
אַתָּה תָקוּם תְּרַחֵם צִיּון כִּי עֵת לְחֶנְנָהּ כִּי בָא מועֵד: אַתָּה הוּא שְׁהִקְטִירוּ אַבוֹתֵינוּ לְפָנֶיךָ אֶת קְטוֹרֶת הַסַּמִים:

פִּטוּם הַקְּטֹרֶת (א) הַצֳּרִי (ב) וְהַצִּפֹּרֶן, (ג) וְהַחֶלְבְּנָה (ד) וְהַלְּבוֹנָה מִשְׁקַל שִׁבְעִים שִׁבְעִים מָנֶה, (ה) מֹר (ו) וּקְצִיעָה, (ז) שִׁבֹּלֶת נֵרְדְּ (ח) וְכַרְכֹּם מִשְׁקַל שִׁשָּׁה עָשָׂר שִׁשָּׁה עָשָׂר מָנֶה, (ט) הַקֹּסְטְ שְׁנֵים עָשָׂר, (י) וְקִלּוּפָה שְׁלֹשָׁה, (יא) וְקִנָּמון תִּשְׁעָה, בֹּרִית כַּרְשִׁינָה תִּשְׁעָה קַבִּין, יֵין קַפְרִיסִין סְאִין תְּלָתָא וְקַבִּין תְּלָתָא, וְאִם לוׂ יֵין קַפְרִיסִין מֵבִיא חֲמַר חִוַּרְיָן עַתִּיק. מֶלַח סְדוֹמִית רֹבַע מַעֲלֶה עָשָׁן כָּל שֶׁהוּא. רַבִּי נָתָן הַבַּבְלִי אוֹמֵר: אַף כִּפַּת הַיַּרְדֵּן כָּל שֶׁהוּא. וְאִם נָתַן בָּהּ דְּבַשׁ פְּסָלָהּ, וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב.

רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר: הַצֳּרִי אֵינוֹ אֶלָּא שְׂרָף הַנּוֹטֵף מֵעֲצֵי הַקְּטָף. בֹּרִית כַּרְשִׁינָה לָמָה הִיא בָאָה כְדֵי לְיַפוֹת בָּה אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא נָאֶה. יֵין קַפְרִיסִין שֶׁשׁוֹרִין בּוֹ אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא עַזָּה. וַהֲלֹא מֵי רַגְלַיִם יָפִין לָהּ, אֶלָּא שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם בַּעֲזָרָה מִפְּנֵי הַכָּבוֹד.

תַּנְיָא: רַבִּי נָתָן אוֹמֵר: כְּשֶׁהוּא שׁוֹחֵק אוֹמֵר: הָדֵק הֵיטֵב, הֵיטֵב הָדֵק, מִפְּנֵי שֶׁהַקּוֹל יָפֶה לַבְּשָׂמִים.

י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
